package dev.gbppimentel.snapcompanion;
import android.content.Context;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowBuild;import org.robolectric.util.ReflectionHelpers;import java.util.*;import static org.junit.Assert.*;
/** Actual service publication boundary, without projection, shell or device access. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=33)
public class CaptureSourceTest {
 private CaptureService capture;private GameConnection original;private boolean active;
 @Before public void setup(){ShadowBuild.setModel("AYN Thor");Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("snap",0).edit().clear().commit();original=EdenLinkService.connection;active=EdenLinkService.active;EdenLinkService.active=true;EdenLinkService.connection=GameConnection.empty().observed("123",true,System.currentTimeMillis());capture=Robolectric.buildService(CaptureService.class).create().get();ReflectionHelpers.setField(capture,"prefs",c.getSharedPreferences("snap",0));ReflectionHelpers.setField(capture,"store",new LiveStore(c));ReflectionHelpers.setStaticField(CaptureService.class,"readingSource","default:"+EdenLinkService.connection.token());}
 @After public void cleanup(){ReflectionHelpers.setStaticField(CaptureService.class,"instance",null);ReflectionHelpers.setStaticField(CaptureService.class,"readingSource","");EdenLinkService.connection=original;EdenLinkService.active=active;EdenFps.latest=null;}
 @Test public void restartRejectsOldPublishedFrameEvenWithMatchingCompanionProfile(){long now=System.currentTimeMillis();assertTrue(CaptureService.currentSource("default",now));EdenLinkService.connection=EdenLinkService.connection.observed("456",true,now);assertFalse(CaptureService.currentSource("default",now));}
 @Test public void hiddenOrExpiredConnectionAndOtherProfileCannotPublishLiveData(){long now=System.currentTimeMillis();assertFalse(CaptureService.currentSource("another",now));EdenLinkService.connection=EdenLinkService.connection.observed("123",false,now);assertFalse(CaptureService.currentSource("default",now));EdenLinkService.connection=new GameConnection("123",true,now-7000,1);assertFalse(CaptureService.currentSource("default",now));}
 @Test public void lostProofAndSamePidReconnectionNeedANewFrame(){long now=System.currentTimeMillis();EdenLinkService.connection=EdenLinkService.connection.disconnected().observed("123",true,now);assertFalse(CaptureService.currentSource("default",now));ReflectionHelpers.setStaticField(CaptureService.class,"readingSource","default:"+EdenLinkService.connection.token());assertTrue(CaptureService.currentSource("default",now));}
 @Test public void clearingAConnectionDropsCurrentFieldsAndFpsButPreservesHistory(){Context c=RuntimeEnvironment.getApplication();var field=new LiveStabilizer.Stable("course","park-night",.98f,1000,2000,3,"fixture","default","visible");var store=new LiveStore(c);store.publish(Map.of("course",field),List.of(field));EdenFps.latest=new EdenFps.Sample(System.currentTimeMillis(),"default","EXPEDITION",59.9f,null,.99f);ReflectionHelpers.setField(capture,"lastReading",new LiveReading(2000,"fixture","default",LiveReading.Scene.EXPEDITION,Map.of()));ReflectionHelpers.callInstanceMethod(capture,"clearGameContext");assertTrue(store.snapshot().isEmpty());assertEquals(1,store.history().length());assertNull(EdenFps.latest);assertNull(CaptureService.currentReading());assertFalse(CaptureService.currentSource("default",System.currentTimeMillis()));}
}
